// The three demos' recorded first runs (start/replay.ts): real runs of each demo's first request, each
// on a setup made from the template below, recorded through the console's own route and stream
// reader. Each event is the stream event as the console received it, `t` ms after the request was
// sent. Content is exactly as it ran. The only changes: sandbox paths read relative (the task's
// folder) or as ~ (the agent's home), the run's own ids are replaced (its task reads `recorded`,
// its response `resp_recorded_<demo>`, its files `recorded-file-<n>`, each file's address the kept
// copy under /demos), and the run's trace and costs, which the self-hosted console never shows, are
// left out. Nothing here is read from a server: playback uses this file and the kept files alone.
// Do not edit by hand; re-record and derive it again.

/** One stream event as the console received it, `t` ms after the request was sent. */
export interface RecordedEvent { t: number; ev: Record<string, unknown> }
/** A file the run produced, kept beside the console (`src`, under /demos/); `name` as the run cited it. */
export interface RecordedFile { name: string; mime: string; bytes: number; src: string }
/** A skill of a demo's setup: the design's name and text, and the entry the setup stores (SKILL.md). */
export interface DemoSkill { id: string; name: string; body: string; skill: { name: string; enabled: boolean; files: { path: string; content: string }[] } }
/** A plugin of a demo's setup; `id` 'media' is the image generation tools the run had. */
export interface DemoPlugin { id: string; name: string }
/** What a demo's setup is saved with: name, harness (base id) and model, instructions, skills, plugins. */
export interface DemoTemplate { demo: number; name: string; base: string; model: string; instructions: string; skills: DemoSkill[]; plugins: DemoPlugin[] }
/** One real run of a demo's first request. */
export interface RecordedRun {
  /** the demo it is the first request of (its index in DEMOS) */
  demo: number;
  /** when the request was sent (ms since epoch) */
  ranAt: number;
  /** the agent harness (base id) and the model it ran on */
  base: string; model: string;
  /** the request, exactly as sent */
  request: string;
  /** ms from the request to its terminal event (response.completed) */
  durMs: number;
  /** the terminal response's status */
  status: string;
  events: RecordedEvent[];
  files: RecordedFile[];
  /** the setup it ran on */
  template: DemoTemplate;
}


